python << 'PYEOF'
import json
with open('<workspace>/evidence.json', 'r') as f:
    evidence = json.load(f)
# Verify all required fields and values
errors = []

# Check schema_version
if evidence.get('schema_version') != 1:
    errors.append(f"schema_version should be 1, got {evidence.get('schema_version')}")

# Check sample_id
if not evidence.get('sample_id'):
    errors.append("sample_id is empty")

# Check clip_id
if not evidence.get('clip_id'):
    errors.append("clip_id is empty")

# Check decision
if evidence.get('decision') not in ('report', 'abstain'):
    errors.append(f"decision should be 'report' or 'abstain', got {evidence.get('decision')}")
elif evidence['decision'] == 'report' and evidence['reported_count'] == 0:
    errors.append("report with 0 targets should use decision: abstain")

# Check reported_count
if evidence.get('reported_count') != len(evidence.get('reported_targets', [])):
    errors.append(f"reported_count ({evidence.get('reported_count')}) != len(reported_targets) ({len(evidence.get('reported_targets', []))})")

# Check reported_targets structure
for i, target in enumerate(evidence.get('reported_targets', [])):
    if 'target_ref' not in target:
        errors.append(f"target {i} missing target_ref")
    if 'color_name' not in target:
        errors.append(f"target {i} missing color_name")
    if 'interval_frames' not in target:
        errors.append(f"target {i} missing interval_frames")
    elif len(target['interval_frames']) != 2:
        errors.append(f"target {i} interval_frames should have exactly 2 items, got {len(target['interval_frames'])}")
    if 'anchors' not in target:
        errors.append(f"target {i} missing anchors")
    elif len(target['anchors']) != 2:
        errors.append(f"target {i} anchors should have exactly 2 items, got {len(target['anchors'])}")
    else:
        for j, anchor in enumerate(target['anchors']):
            required_anchor_fields = ['frame_id', 'timestamp_sec', 'roi_xyxy', 'frame_path', 'claim', 'observation_ref']
            for field in required_anchor_fields:
                if field not in anchor:
                    errors.append(f"target {i} anchor {j} missing {field}")

# Check windows_examined
if not evidence.get('windows_examined') or len(evidence['windows_examined']) < 1:
    errors.append("windows_examined is missing or empty")
else:
    for w in evidence['windows_examined']:
        if len(w) != 2:
            errors.append(f"window should have 2 elements, got {len(w)}")

# Check frames_processed
if not isinstance(evidence.get('frames_processed'), int) or evidence['frames_processed'] < 0:
    errors.append(f"frames_processed should be a non-negative integer, got {evidence.get('frames_processed')}")

# Check tool_trace
if not evidence.get('tool_trace') or len(evidence['tool_trace']) == 0:
    errors.append("tool_trace is missing or empty")

if errors:
    print("ERRORS FOUND:")
    for e in errors:
        print(f"  - {e}")
else:
    print("ALL VALIDATION CHECKS PASSED ✓")
    print(f"  - schema_version: {evidence['schema_version']}")
    print(f"  - sample_id: {evidence['sample_id']}")
    print(f"  - clip_id: {evidence['clip_id']}")
    print(f"  - decision: {evidence['decision']}")
    print(f"  - reported_count: {evidence['reported_count']}")
    print(f"  - reported_targets: {len(evidence['reported_targets'])} target(s)")
    for i, t in enumerate(evidence['reported_targets']):
        print(f"    {i+1}. {t['target_ref']} (color: {t['color_name']}, interval: {t['interval_frames']})")
    print(f"  - windows_examined: {evidence['windows_examined']}")
    print(f"  - frames_processed: {evidence['frames_processed']}")
    print(f"  - tool_trace: {len(evidence['tool_trace'])} entries")
PYEOF
